// Force dynamic rendering on each request
export const dynamic = 'force-dynamic';

export default function Home() {
  // This timestamp will be different on every request
  const timestamp = new Date().toISOString();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>Current server time: <strong>{timestamp}</strong></p>
      <p style={{ marginTop: '1rem', color: '#666', fontSize: '0.9rem' }}>
        This timestamp is generated on the server on each request and will be different every time you refresh the page.
      </p>
    </main>
  );
}

